"da — raspoređeno na stavke",
"da se o navodima iz ovog upozorenja pisano izjasnite u roku od {0} dana od dana dostavljanja, najkasnije do {1} godine, i priložite dokaze kojima raspolažete. Ako se u tom roku ne izjasnite, smatra se da ste saglasni sa navodima iz upozorenja ({2} st. 5 i 6). Imate pravo da u roku od {3} dana od dostavljanja (do {4}) zahtijevate da se izjasnite usmeno — rasprava se tada održava u roku od 15 dana od dostavljanja upozorenja, u prisustvu predstavnika sindikata čiji ste član i branioca koga sami izaberete, ako to zahtijevate, i o njoj se vodi zapisnik ({5} st. 7–12).",
