"Poštovani,\\n\\nu Vašoj kartici / IOS-u za {0} na dan {1}. nalaze se stavke koje nemaju pokriće u našoj evidenciji:\\n\\n{2}\\n\\nUkupno sporno: {3} EUR.\\n\\nMolimo Vas da nam za navedene stavke dostavite kopije faktura i otpremnica sa potpisom lica koje je preuzelo robu (ime, prezime, objekat), odnosno da ispravite karticu ako je riječ o grešci. Do usaglašavanja te stavke ne možemo smatrati dospjelim za plaćanje niti ovjeriti IOS.\\n\\nSrdačan pozdrav,\\n{4}",
