"Pravilnik 34/12 čl. 11: promjena cijene robe upisuje se u evidenciju trgovine na osnovu izvještaja o izvršenom popisu. Povećanje se upisuje kao zaduženje, smanjenje crvenim stornom (kol. 4). Nova cijena važi od dana nivelacije u lageru i cjenovniku kase; istorija cijena ostaje (Zakon o zaštiti potrošača čl. 15).",
"Pravilnik 34/12 čl. 3 st. 1: evidencija se vodi posebno za svako veleprodajno mjesto i prodavnicu. Veleprodaja: evidencija EV, konta 1320/1329, 5012, 6020. Maloprodaja: evidencija EM, konta 134000/134001/134002, 5013, 6021. Vrsta se mijenja samo dok objekat nema dokumenata.",
"Pravilnik 34/12 čl. 3: evidencija trgovine vodi se posebno za svako prodajno mjesto. Pošiljalac: kol. 4 crveni storno po svojoj prodajnoj vrijednosti; primalac: kol. 4 zaduženje po internoj kalkulaciji. PPZPDV čl. 80: interni računi ne utiču na poresku obavezu.",
