"Za uplatu je izdat avansni račun. Uplata se ne briše dok avansni račun postoji.",
"Za vrijeme godišnjeg odmora zaposlenom pripada naknada zarade u visini zarade koju bi ostvario da radi ({0}). Zaposleni kome radni odnos prestaje, a nije iskoristio godišnji odmor, ima pravo na naknadu štete prema prosječnoj zaradi ostvarenoj kod Poslodavca u godini u kojoj je pravo stečeno, srazmjerno neiskorišćenim danima ({1}); Poslodavac je dužan da mu omogući korišćenje odmora prije prestanka kad god je to moguće.",
"Za vrijeme manifestacije",
"Za zasnivanje radnog odnosa na svakom radnom mjestu zaposleni mora ispunjavati opšte uslove propisane zakonom (navršenih 15 godina života i opšta zdravstvena sposobnost), a za radna mjesta na kojima se rukuje namirnicama i sanitarno-zdravstvene uslove propisane za lica koja rade u prometu hrane (sanitarni pregled). Zaposleni se prije stupanja na rad osposobljava za bezbjedan rad u skladu sa propisima o zaštiti i zdravlju na radu. Za radna mjesta sa materijalnom odgovornošću (novac, roba) ugovorom o radu utvrđuje se obaveza čuvanja povjerenih sredstava i naknade štete.",
