"Zaključni nalog na 31.12.: prihodi (klasa 6) i rashodi (klasa 5) prenose se preko 699/599 na 710, rezultat na 720, porez na dobit 721/4810, a neto dobitak na 3410 (gubitak na 3510). Otvaranje naredne godine prenosi salda klasa 0–4 u početno stanje 01.01. Prije zaključka: svi mjeseci proknjiženi, popis i amortizacija knjiženi, PD prijava snimljena (daje tačan porez).",
